import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,E as n,M as r,N as i,O as a,P as o,S as s,_ as c,a as l,b as u,c as d,k as f,l as p,o as m,p as h,t as g}from"./shared-UmZHo_CQ.js";import{t as _}from"./database-LLH4Psoh.js";import{t as v}from"./search-f2spAuW6.js";import{D as y}from"./index-3E7rQLz6.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e(),S=`Этап 4 · Блок 14 · Подготовить базу, не теряя действующий проект`;function C({module:e}){return(0,x.jsxs)(i,{children:[(0,x.jsx)(r,{variant:`project`,chip:e??S,title:`SQLite и основы SQL`,intro:`Познакомимся с таблицами и запросами на отдельной учебной базе. Действующий Planner пока продолжит читать и сохранять JSON.`,tags:[{icon:(0,x.jsx)(_,{size:14}),label:`SQLite в памяти`},{icon:(0,x.jsx)(v,{size:14}),label:`SQL-запросы`},{icon:(0,x.jsx)(y,{size:14}),label:`изолированный опыт`}]}),(0,x.jsxs)(o,{number:`00`,title:`От полного JSON к одной строке`,children:[(0,x.jsx)(a,{children:`Наш Planner уже сохраняет задачи между запусками. Сейчас он работает с файлом JSON и знакомой моделью Task. Перед подключением базы данных нам нужно понять одну новую идею: как обратиться к отдельной записи, не принимая таблицу за список Python-объектов.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`У нас есть JSON, который хранит полный список задач, и операции Planner, которые продолжают работать с этим списком.`},{title:`Новый вопрос`,description:`Как таблица помогает выбрать одну строку и изменить её по условию, а не загружать весь файл в Python?`},{title:`Результат`,description:`Мы создадим таблицу в памяти и проверим параметризованные INSERT, SELECT, UPDATE и DELETE на учебных данных.`}]}),(0,x.jsx)(`p`,{children:`Сначала восстановим нужную связь: JSON уже является постоянным хранилищем, но его обычная операция может прочитать список целиком, найти в нём задачу, а затем сохранить обновлённый список. Если мы ещё не разбирали эту цену полного снимка, сейчас достаточно именно этого короткого напоминания. Дальше посмотрим, как SQLite представляет данные строками и как SQL задаёт выборку. Все запросы пройдут на отдельной базе в памяти. Мы не будем переносить туда Planner и не изменим его API, CLI или JSON.`})]}),(0,x.jsxs)(o,{number:`01`,title:`SQLite открывает отдельную базу для опыта`,children:[(0,x.jsx)(a,{children:`SQLite хранит данные в реляционной базе, то есть в наборе связанных таблиц. Это встроенная библиотека: для локального эксперимента нам не нужен отдельный сервер базы данных.`}),(0,x.jsx)(`p`,{children:`У базы может быть файл на диске, но для короткого опыта мы передадим строку :memory:. Вызов sqlite3.connect(':memory:') открывает соединение с новой базой в оперативной памяти. Переменная connection обозначает именно это соединение: через него мы отправляем SQL, читаем ответы, подтверждаем или отменяем изменения. Она не является самой таблицей, моделью Task или всей будущей инфраструктурой приложения.`}),(0,x.jsx)(`p`,{children:`Представим, что соединение это отдельный рабочий стол в учебной лаборатории. Таблицы и строки лежат на нём, пока открыт этот сеанс; connection позволяет подойти к столу и выполнить команду. Аналогия помогает помнить границу времени жизни, но SQLite работает с данными по своим правилам и может использовать как память, так и обычный файл. Закрытие соединения с :memory: уничтожит эту временную базу. Подключение к другому файлу или к другому соединению не подхватит её автоматически.`}),(0,x.jsx)(`p`,{children:`На схеме мы разделили отправку команды и получение результата. Скрипт обращается к открытой базе через connection. SQLite обрабатывает запрос над таблицей, а cursor, который возвращает execute(), даёт нам доступ к выбранным строкам. Этот маршрут понадобится во всех следующих примерах, хотя сам курсор отдельно создавать не обязательно: connection.execute() делает это за нас.`}),(0,x.jsxs)(g,{caption:`Запрос проходит через открытое соединение и возвращает строки из базы.`,orientation:`horizontal`,children:[(0,x.jsxs)(m,{label:`Обмен Python и SQLite`,orientation:`horizontal`,className:`lesson79-sqlite-flow`,children:[(0,x.jsx)(d,{title:`Код Python`,children:(0,x.jsx)(p,{title:`Connection`,shape:`input-output`,children:(0,x.jsx)(`p`,{children:`Отправляет SQL и параметры`})})}),(0,x.jsx)(l,{forward:`SQL + значения`,reverse:`результаты запроса`}),(0,x.jsx)(d,{title:`База SQLite`,children:(0,x.jsx)(p,{title:`Таблица`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Хранит строки и колонки`})})})]}),(0,x.jsx)(n,{tone:`info`,children:`База в памяти принадлежит открытому соединению. Закрытие завершает этот опыт, а не сохраняет файл Planner.`})]}),(0,x.jsx)(u,{question:`Что создаёт sqlite3.connect(':memory:') для нашего опыта?`,options:[`Отдельную временную базу, доступную через открытое соединение.`,`Постоянную таблицу внутри рабочего JSON Planner.`,`Готовый SQLAlchemy Engine и ORM-модель Task.`],correctIndex:0,explanation:`Мы открываем изолированную базу в памяти стандартным модулем sqlite3. Здесь ещё нет SQLAlchemy, таблиц рабочего Planner или переноса данных.`})]}),(0,x.jsxs)(o,{number:`02`,title:`Таблица хранит строки, а не экземпляры Task`,children:[(0,x.jsx)(a,{children:`В таблице каждая запись занимает строку, а каждое свойство записи имеет свою колонку. Схема задаёт имена колонок, объявленные типы и некоторые ограничения.`}),(0,x.jsx)(`p`,{children:`Например, учебная таблица может содержать id, title, priority и is_done. id будет первичным ключом: по нему мы различаем строки. Он похож на номер заказа в журнале. Номер позволяет снова найти запись, даже если строки отсортировали иначе. Однако id не обещает порядок чтения. Когда порядок имеет значение, его нужно задавать в запросе.`}),(0,x.jsx)(`p`,{children:`Объявление INTEGER или TEXT сообщает SQLite, какие значения ожидаются в колонке; это не такая же гарантия, как тип аннотации Python. У SQLite есть правила хранения и приведения значений, а в обычной таблице объявленный тип не всегда означает строгий запрет других форм данных. Для нашей маленькой схемы мы заранее используем целые числа и текст. Ограничение NOT NULL отдельно говорит, что поле нельзя оставить пустым значением SQL. Первичный ключ также требует уникального идентификатора.`}),(0,x.jsx)(`p`,{children:`SQL NULL обозначает отсутствие значения. Когда sqlite3 возвращает такую ячейку в Python, мы увидим None. Это не то же самое, что пустая строка, число 0 или False. Например, состояние is_done в этой лаборатории передаётся как 0 или 1. Эти значения не становятся автоматически логическим свойством Task, потому что строка результата это набор значений колонок, а не экземпляр нашего класса.`}),(0,x.jsx)(`p`,{children:`Сравним строку таблицы с бумажной карточкой в каталоге. Колонки это подписанные поля карточки, строка это заполненная карточка, а первичный ключ это устойчивый инвентарный номер. Python-объект Task может содержать правила, методы и дополнительные преобразования; у обычной строки SQLite таких методов нет. На этом шаге мы изучаем данные и команды, а преобразование между таблицей и предметной моделью будет отдельной темой.`}),(0,x.jsx)(b,{caption:`Так мы описываем только учебную таблицу`,code:`connection.execute("""
CREATE TABLE tasks (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    priority INTEGER NOT NULL,
    is_done INTEGER NOT NULL
)
""")`}),(0,x.jsx)(u,{question:`Что получим из sqlite3 при SELECT id, title, если совпала одна строка?`,options:[`Кортеж со значениями двух выбранных колонок.`,`Готовый экземпляр Task со всеми методами.`,`Полный словарь настроек приложения.`],correctIndex:0,explanation:`По умолчанию sqlite3 возвращает строку как кортеж. Мы сами видим выбранные колонки, их порядок и значения. ORM-преобразования здесь ещё нет.`}),(0,x.jsx)(u,{question:`Если nullable-колонка хранит SQL NULL, что мы увидим в возвращённой строке Python?`,options:[`None`,`False`,`Пустую строку`],correctIndex:0,explanation:`SQL NULL обозначает отсутствие значения и преобразуется sqlite3 в Python None. Ноль, False и пустая строка являются другими значениями.`})]}),(0,x.jsxs)(o,{number:`03`,title:`SELECT читает результат, а условия уточняют строки`,children:[(0,x.jsx)(a,{children:`SELECT перечисляет колонки, FROM указывает таблицу, а WHERE оставляет строки, удовлетворяющие условию. Затем мы можем определить порядок и ограничить количество результатов.`}),(0,x.jsx)(`p`,{children:`У каждого запроса есть текст и ожидаемый результат. Выполняя connection.execute(...), мы получаем cursor. Метод fetchone() возвращает следующую найденную строку кортежем. Если подходящей строки нет, fetchone() возвращает None. fetchall() забирает оставшиеся строки в список кортежей. Если SELECT указал три колонки, каждый кортеж содержит эти три значения в том же порядке.`}),(0,x.jsx)(`p`,{children:`Представим каталог читального зала. WHERE выбирает записи, например только места во втором зале или выше. ORDER BY сортирует найденное по указанной колонке. LIMIT оставляет первые N строк уже упорядоченного результата. Поэтому LIMIT не заменяет фильтр, а сортировка не меняет данные в таблице.`}),(0,x.jsx)(`p`,{children:`Если мы забыли ORDER BY, SQLite может вернуть строки в порядке, удобном для внутреннего выполнения запроса. Сегодня они могут выглядеть так же, как вставлялись, но это не обещание SQL. Если сортируем только по залу, несколько строк одного зала между собой также не получают заданного порядка. Когда он важен, добавим второй ключ, например id. Эти различия особенно заметны, когда на результат влияет LIMIT.`}),(0,x.jsx)(`p`,{children:`При поиске одной строки мы выберем только нужные колонки и зададим WHERE id = ?. Если идентификатора нет, получим None и сможем объяснить, что совпадение не найдено. Мы не создаём пустую задачу по умолчанию и не превращаем tuple в объект Planner. Так результат остаётся точным отражением запроса.`}),(0,x.jsx)(h,{prompt:`Соединим часть запроса с её ролью.`,leftTitle:`Часть`,rightTitle:`Что делает`,pairs:[{left:`WHERE`,right:`отбирает подходящие строки`},{left:`ORDER BY`,right:`задаёт порядок результата`},{left:`LIMIT`,right:`ограничивает число строк`},{left:`fetchone()`,right:`возвращает одну строку или None`}],explanation:`Каждая часть отвечает за отдельный шаг: фильтрацию, порядок, количество или получение строки из результата.`}),(0,x.jsx)(n,{tone:`info`,children:`Порядок колонок определяется списком после SELECT. Порядок строк определяется ORDER BY. Это два разных вида порядка.`})]}),(0,x.jsxs)(o,{number:`04`,title:`Параметры передают значения отдельно от SQL`,children:[(0,x.jsx)(a,{children:`Данные могут содержать кавычку, пробел или текст, похожий на часть команды. Поэтому значение передаётся не склейкой строк, а отдельным параметром.`}),(0,x.jsx)(`p`,{children:`У connection.execute() есть два аргумента: сначала текст SQL, затем последовательность значений для знаков вопроса. Плейсхолдер ? отмечает место значения. SQLite связывает его с элементом параметров по позиции. Первый знак вопроса получает первый элемент, следующий знак получает следующий элемент. Число и порядок значений должны совпадать с запросом.`}),(0,x.jsx)(`p`,{children:`Это похоже на бланк заказа и отдельно приложенный конверт с данными. Бланк определяет поля и порядок, а содержимое конверта заполняет эти места, не переписывая сам бланк. Граница аналогии в том, что SQL-драйвер связывает параметры по правилам протокола, а не открывает настоящий конверт. Для нас важно разделение текста запроса и пользовательских значений.`}),(0,x.jsx)(b,{caption:`Пример с другой таблицей, не с Planner`,code:`attendee_name = "O'Neil"
connection.execute(
    "INSERT INTO signups (name, topic) VALUES (?, ?)",
    (attendee_name, "SQLite basics"),
)`}),(0,x.jsx)(`p`,{children:`Кавычка в имени не завершает запрос: она является значением. Мы не ставим кавычки вокруг самого знака ? и не собираем команду f-строкой. Склейка SQL с текстом может сломаться на кавычке, а также позволяет данным менять смысл команды. Параметры решают эту границу для значений. Имя таблицы и имя колонки не являются значениями и не заменяются таким плейсхолдером.`}),(0,x.jsx)(`p`,{children:`Параметры используются для чтения и изменения одинаково. В SELECT мы передадим id или условие фильтра; в INSERT, UPDATE и DELETE передадим текст или новые поля. Запрос остаётся виден как структура, а конкретные данные остаются отдельными аргументами. Так мы можем передать даже значение с кавычкой без ручного экранирования.`}),(0,x.jsx)(t,{code:`name = "O'Neil"
connection.execute(
    f"SELECT name FROM signups WHERE name = '{name}'"
)`,question:`Почему этот поиск может сломать запрос, и как мы исправим причину?`,options:[`Имя склеивается с SQL, поэтому кавычка попадает в текст команды. Передадим имя через ? и кортеж параметров.`,`SQLite не хранит текст. Заменим имя на число перед выполнением.`,`WHERE всегда запрещает имена с апострофом. Уберём условие целиком.`],correctIndex:0,explanation:`Значение участвует в построении SQL-строки, поэтому апостроф меняет её кавычки. Параметр отделяет данные от команды и сохраняет имя целиком.`,fix:`connection.execute(
    "SELECT name FROM signups WHERE name = ?",
    (name,),
)`})]}),(0,x.jsxs)(o,{number:`05`,title:`INSERT, UPDATE и DELETE меняют конкретные строки`,children:[(0,x.jsx)(a,{children:`После чтения рассмотрим три команды изменения: вставку новой строки, обновление колонок существующей строки и удаление строки.`}),(0,x.jsx)(`p`,{children:`INSERT перечисляет колонки и передаваемые значения. Первичный ключ можно указать явно, но SQLite также умеет выдать новый id, когда колонка INTEGER PRIMARY KEY не передана. В коротком эксперименте мы оставим id базе и будем использовать полученные значения для последующих адресных запросов.`}),(0,x.jsx)(`p`,{children:`UPDATE задаёт колонки и новые значения после SET. WHERE выбирает, какие строки изменятся. Например, WHERE id = ? ограничивает работу одной записи. DELETE использует похожую идею, но удаляет выбранные строки целиком. Значения в SET, INSERT и условии снова передаются параметрами, а не включаются в текст через f-строку.`}),(0,x.jsx)(`p`,{children:`Условия здесь важнее короткого синтаксиса. UPDATE без WHERE меняет заданные колонки у всех строк таблицы. DELETE без WHERE удаляет все её строки. Это не означает, что запрос неисправен: он действует на весь набор, потому что мы не указали фильтр. Поэтому перед выполнением изменения мы читаем WHERE как границу охвата и заранее предсказываем список строк.`}),(0,x.jsx)(`p`,{children:`Вернёмся к аналогии карточек в каталоге. UPDATE заменяет выбранное поле у карточек с подходящим номером, а DELETE убирает такие карточки из каталога. Если указатель номера убрать, команда перестаёт выбирать одну карточку и распространяется на все строки. Аналогия ограничена: в базе охват задаётся логическим условием, а не физическим указателем.`}),(0,x.jsx)(h,{prompt:`Сопоставим команды с результатом на уровне таблицы.`,leftTitle:`Команда`,rightTitle:`Изменение`,pairs:[{left:`INSERT`,right:`добавляет строку`},{left:`UPDATE`,right:`меняет значения колонок`},{left:`DELETE`,right:`удаляет выбранные строки`},{left:`UPDATE без WHERE`,right:`меняет строки по всей таблице`}],explanation:`Команда задаёт тип изменения, а WHERE определяет его охват. Для INSERT новые строки добавляются указанными значениями.`}),(0,x.jsx)(c,{code:`import sqlite3

connection = sqlite3.connect(":memory:")
connection.execute(
    "CREATE TABLE checkins (id INTEGER PRIMARY KEY, name TEXT, room INTEGER)"
)
connection.execute("INSERT INTO checkins (name, room) VALUES (?, ?)", ("Алия", 2))
connection.execute("INSERT INTO checkins (name, room) VALUES (?, ?)", ("Бек", 1))
connection.execute("INSERT INTO checkins (name, room) VALUES (?, ?)", ("Данил", 3))

rows = connection.execute(
    "SELECT id, name, room FROM checkins WHERE room >= ? ORDER BY room ASC, id ASC LIMIT ?",
    (2, 2),
).fetchall()
print(rows)
connection.close()`,output:`[(1, 'Алия', 2), (3, 'Данил', 3)]`,hint:`Сначала оставляем зал 2 и выше, затем сортируем по номеру зала и берём первые две строки.`}),(0,x.jsx)(`p`,{children:`В прогнозе мы выбрали независимую таблицу посещений, чтобы отдельно связать уже разобранные SELECT, параметры и сортировку. Когда ответ откроется, мы проверим, что id относится к первой колонке, фильтр удалил зал 1, а LIMIT ограничил результат двумя строками. Это результат только текущего SQL-запроса, не готовые объекты приложения.`})]}),(0,x.jsxs)(o,{number:`06`,title:`commit, rollback и close выполняют разные действия`,children:[(0,x.jsx)(a,{children:`Выполненная команда изменения и завершённая транзакция не всегда одно и то же. Мы отдельно подтверждаем нужные изменения, отменяем незавершённые и закрываем соединение.`}),(0,x.jsx)(`p`,{children:`После INSERT, UPDATE или DELETE при обычном режиме соединения sqlite3 может вести транзакцию с ожидающими подтверждения изменениями. commit() завершает эту группу как принятую. rollback() отменяет ещё не подтверждённые изменения и возвращает таблицу к последнему подтверждённому состоянию. Если запрос не попал в нужную строку, чтение после изменения помогает заметить это, но не заменяет выбор момента фиксации.`}),(0,x.jsx)(`p`,{children:`Важная граница: пока соединение открыто, оно видит собственные изменения и до commit(). Поэтому чтение того же соединения покажет временное значение, хотя транзакция ещё не завершена. После rollback() мы увидим прежнее значение. commit() оставляет подтверждённые изменения в этой базе, но не превращает :memory: в файл: всё равно закрытие соединения завершает опыт и освобождает базу.`}),(0,x.jsx)(`p`,{children:`Представим черновик заявки. Пока мы его не подтвердили, можем отменить текущие правки и вернуться к последней принятой версии. Это помогает вспомнить роль commit и rollback. Но close это отдельное действие: закрыть рабочее окно не значит сохранить черновик. В нашей программе close() освобождает соединение; если база была создана в памяти, доступ к ней после этого закончится.`}),(0,x.jsx)(`p`,{children:`У connection есть контекстный менеджер: блок with connection может подтвердить транзакцию при нормальном завершении и отменить её при исключении. Само соединение он не закрывает. Значит, граница блока with и вызов connection.close() решают разные задачи. В этой лаборатории мы вызовем close() явно, чтобы не спутать завершение транзакции с окончанием времени жизни базы.`}),(0,x.jsx)(s,{statement:`Если мы выйдем из блока with connection, объект Connection обязательно закроется.`,isTrue:!1,explanation:`Контекстный менеджер соединения управляет завершением транзакции, но не вызывает close(). Соединение нужно закрыть отдельно.`}),(0,x.jsx)(n,{tone:`warn`,children:`Не запускаем UPDATE или DELETE без WHERE на рабочих данных. В нашем плане такой запрос только разбирается словами, а все команды выполняются в отдельной базе :memory:.`})]}),(0,x.jsxs)(o,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(a,{children:`Мы проведём небольшой опыт с sqlite3, чтобы увидеть таблицу и запросы до появления SQLAlchemy. В рабочем Planner после этого занятия ничего не поменяется.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Откроем соединение`,description:`Создадим таблицу tasks в :memory: и получим пустую схему с первичным ключом и четырьмя колонками.`},{title:`Добавим значения`,description:`Передадим несколько задач отдельными параметрами, включая title с апострофом, и увидим новые строки.`},{title:`Предскажем выборки`,description:`Сверим WHERE, ORDER BY, LIMIT и пустой результат для неизвестного id с тем, что вернёт sqlite3.`},{title:`Изменим две записи`,description:`Обновим приоритет одной задачи, удалим другую по id и объясним последствия пропущенного WHERE.`},{title:`Завершим опыт`,description:`Подтвердим основные изменения, отменим отдельное временное изменение, перечитаем строку и закроем соединение.`}]}),(0,x.jsx)(`p`,{children:`Практика пройдёт в одном интерпретаторе Python на стандартном sqlite3 и одном открытом соединении. Мы используем только временную таблицу и знакомые поля задачи. Перед каждой выборкой спрогнозируем строки; перед изменением назовём его охват. В рабочий JSON не обращаемся, второй источник данных для Planner не создаём.`}),(0,x.jsx)(`p`,{children:`На выходе мы будем различать базу, соединение, таблицу, строку, колонку и Task; сможем прочитать и адресно изменить учебную запись. В следующем занятии применим SQLAlchemy Engine к выбору адреса и проверке подключения. Engine, ORM, Session и таблица рабочего Planner здесь ещё не появляются.`})]})]})}export{C as Lesson79};